    "Defender, ASR, App Control, Firewall, Prozess-Telemetrie, Threat Intelligence, Dateiintegrität und Evidence werden lokal zusammengeführt. Keine Cloud-Abhängigkeit, keine CDN-Ressourcen.": "Defender, ASR, App Control, firewall, process telemetry, Threat Intelligence, file integrity and evidence are merged locally. No cloud dependency, no CDN resources.",
    "Defender, Firewall, Plattform, Identität, Logging und Evidenz werden geprüft.": "Defender, firewall, platform, identity, logging and evidence are checked.",
    "defender.asrRules": "defender.asrRules",
    "defender.cloudBlockLevel": "defender.cloudBlockLevel",
    "defender.controlledFolderAccess": "defender.controlledFolderAccess",
    "defender.mapsReporting": "defender.mapsReporting",
