    "Freigeben (Whitelist)": "Allow (Whitelist)",
    "Freigegebene Pfade oder IP-Ziele werden sofort aus aktiven Kernel-WFP-Sperren gelöst und künftig nicht mehr blockiert.": "Allowed paths or IP targets are immediately released from active kernel WFP blocks and will not be blocked in the future.",
    "Für „{0}“ werden echte Windows-Firewall-Regeln (ausgehend und eingehend, Aktion Block) erzeugt. Die Transaktion wird protokolliert und kann über „Sperre aufheben“ zurückgenommen werden.": "Real Windows firewall rules (outbound and inbound, action Block) are created for “{0}”. The transaction is logged and can be reversed via “Remove block”.",
    "Für Alltag, Browser, Kommunikation und persönliche Dateien. Empfohlen: vollständiger Defender-Schutz, ASR/CFA im Blockmodus, Firewall, Titan STRICT und Integritätsüberwachung.": "For everyday tasks, browsing, communication, and personal files. Recommended: full Defender protection, ASR/CFA blocking, Firewall, Titan STRICT, and integrity monitoring.",
    "Für Arbeitsplätze mit geschäftlichen Daten und mehreren Schutzschichten. Empfohlen: EnterpriseBalanced, alle ASR-Regeln im Blockmodus, CFA, Firewall, Titan STRICT und lückenlose Evidenz.": "For workstations handling business data with multi-layer protection. Recommended: EnterpriseBalanced, all ASR rules in block mode, CFA, Firewall, Titan STRICT, and complete evidence.",
    "Für dauerhaft laufende Systeme ohne lokale Bedienung. Empfohlen: Isolation-Profil mit zusätzlich deaktiviertem USB-Speicher und RDP, Defender vollständig blockierend, Firewall und Titan STRICT.": "For continuously running systems without local operation. Recommended: Isolation profile with USB storage and RDP disabled, full blocking Defender, Firewall, and Titan STRICT.",
    "Für die Aktivierung ist eine Operator-Sitzung erforderlich. Bitte über das Security Center anmelden und erneut versuchen.": "An operator session is required for activation. Please sign in via Security Center and try again.",
    "Für diese Komponente ist keine feingranulare Konfiguration vorgesehen; sie wird als Ganzes angewendet oder zurückgerollt.": "No fine-grained configuration is provided for this component; it is applied or rolled back as a whole.",
    "Für eine unabhängige Prüfung.": "For independent verification.",
    "Für lokale Entwicklung und Builds. Empfohlen: EnterpriseBalanced, Defender blockierend, Titan STRICT mit Entwicklungsbaum und expliziten Owner-Prozessketten. Automatische Quarantäne bleibt hier aus.": "For local development and builds. Recommended: EnterpriseBalanced, blocking Defender, Titan STRICT with development roots and explicit owner process chains. Auto-quarantine stays off.",
    "geblockt": "blocked",
