    "CRITICAL": "CRITICAL",
    "CRITICAL — nur kritische Blocks": "КРИТИЧЕСКИЙ — только критические блокировки",
    "Cross-Engine Schutzbrücke für kompromittierte Persistenz.": "Межмодульный защитный мост для скомпрометированной персистентности.",
    "CURRENT": "CURRENT",
    "currentColor": "currentColor",
    "currentMode": "currentMode",
