    "CUSTOM PROTECTION PROFILE": "ПОЛЬЗОВАТЕЛЬСКИЙ ПРОФИЛЬ ЗАЩИТЫ",
    "Das aktive Profil kann nicht entfernt werden.": "Активный профиль нельзя удалить.",
    "Das Aktivieren erweitert die erlaubte Ausführungsfläche. Die Begründung wird auditierbar protokolliert.": "Включение расширяет допустимую поверхность выполнения. Обоснование записывается в журнал аудита.",
    "Das Deaktivieren senkt die Erkennungsabdeckung. Die Begründung wird auditierbar protokolliert.": "Отключение снижает охват обнаружения. Причина фиксируется в аудиторском журнале.",
    "Das Deaktivieren verschärft die Schutzlage. Die Begründung wird auditierbar protokolliert.": "Отключение ужесточает режим защиты. Обоснование записывается в журнал аудита.",
    "Das Entfernen verschärft die Schutzlage. Die Begründung wird auditierbar protokolliert.": "Удаление ужесточает режим защиты. Обоснование записывается в журнал аудита.",
    "Das Herabstufen von Aktiv/WFP-Enforce auf Observe oder Aus reduziert die aktive Durchsetzung. Bitte Begründung angeben.": "Переход с «Активный / WFP Enforce» на «Наблюдение» или «Выкл» снижает активную защиту. Укажите причину.",
    "Das Intervall wird serverseitig persistiert, sobald die Settings-API verfügbar ist. Ohne Backend bleibt eine Auswahl nur lokal in dieser Sitzung und wird nicht als gespeichert ausgegeben.": "Интервал сохраняется на стороне сервера, как только становится доступен API настроек. Без серверной части выбор остается только локально в этой сессии и не отображается как сохраненный.",
    "Das senkt die aktive Schutzstufe. Die Begründung wird auditierbar protokolliert.": "Это снижает активный уровень защиты. Причина фиксируется в аудиторском журнале.",
    "Datei": "Файл",
    "Datei ändern": "Изменить файл",
    "Datei anlegen": "Создать файл",
    "DATEIEN": "ФАЙЛЫ",
    "Dateiereignisse in diesem Baum bleiben vollständig in der Evidenz, werden aber nicht als Ingress-Hochrisiko eskaliert. System- und Persistenzänderungen bleiben unverändert streng.": "Файловые события в этом дереве полностью сохраняются в доказательствах, но не повышаются до высокого риска входящего трафика. Изменения системы и закрепления остаются строгими без изменений.",
    "Dateiintegritäts-Überwachung aktivieren": "Включить мониторинг целостности файлов",
    "Dateiintegritäts-Überwachung deaktivieren": "Отключить мониторинг целостности файлов",
    "Dateipfad": "Путь к файлу",
    "DATEN": "ДАННЫЕ",
    "Daten nicht abrufbar. Die Karte wird automatisch erneut geladen.": "Данные недоступны. Карта будет загружена автоматически повторно.",
    "DATEN NICHT AKTUELL": "ДАННЫЕ УСТАРЕЛИ",
    "Daten nicht aktuell. Angezeigt wird der letzte erfolgreiche Abruf.": "Данные устарели. Показан последний успешный запрос.",
    "Daten: DB-IP Lite (CC BY 4.0, db-ip.com), Origin ASN (PDDL). Näherungswerte, nicht Personenstandorte.": "Данные: DB-IP Lite (CC BY 4.0, db-ip.com), Origin ASN (PDDL). Приблизительные значения, а не местоположение людей.",
    "de-DE": "de-DE",
