    "Ergebnis": "Результат",
    "Ergebnis im Security Center darstellen; Dialog kann offen bleiben.": "Показать результат в Центре безопасности; диалог может оставаться открытым.",
    "Ergebnis nicht dokumentiert": "Результат не задокументирован",
    "Ergebnis vom {0}. Ein neuer Lauf ersetzt die Anzeige, nicht die lokale Evidenz.": "Результат от {0}. Новый запуск заменит отображение, но не локальные доказательства.",
    "Ergebnisse anzeigen": "Показать результаты",
    "Ergebnisse auswerten": "Проанализировать результаты",
    "Ergebnisse erscheinen nach einem abgeschlossenen Audit. Ein neuer Lauf ersetzt die Anzeige, nicht die lokale Evidenz.": "Результаты появляются после завершения аудита. Новый запуск заменяет отображение, но не локальные доказательства.",
    "Ergebnisse werden ausgewertet": "Результаты анализируются",
