    "Erkannte Bursts und Threat-IP-Korrelation": "Обнаруженные всплески и корреляция Threat-IP",
    "Erkannte Dateiveränderungen": "Обнаруженные изменения файлов",
    "Erkennen, korrelieren und protokollieren.": "Обнаруживать, коррелировать и протоколировать.",
    "Erkennt Angriffe auf Anmeldeinformationen wie MiniDumpWriteDump, Sekurlsa und SAM-Export": "Обнаруживает атаки на учётные данные, такие как MiniDumpWriteDump, Sekurlsa и экспорт SAM",
    "Erkennt Base64-obfuskierte Befehlsblöcke ab 60 Zeichen oder fortlaufende Hex-Payloads": "Обнаруживает Base64-обфусцированные командные блоки от 60 символов или непрерывные hex-полезные нагрузки",
    "Erkennt bösartige Living-off-the-Land Parameter wie -enc, -decode, encodedcommand, downloadstring, invoke-expression": "Обнаруживает вредоносные параметры living-off-the-land, такие как -enc, -decode, encodedcommand, downloadstring, invoke-expression",
    "Erkennt das Löschen von Schattenkopien (vssadmin delete), BITS-Transfers und Certutil-Downloads": "Обнаруживает удаление теневых копий (vssadmin delete), BITS-передачи и загрузки Certutil",
    "Erkennt Log4j/JNDI Remote-Exploits sowie Mining-Protokolle (Stratum, Monero, Coinhive)": "Обнаруживает удалённые эксплойты Log4j/JNDI, а также майнинговые протоколы (Stratum, Monero, Coinhive)",
    "Erkennt und protokolliert, blockiert nicht. Für Analyse und Erstinbetriebnahme, nicht als Dauerzustand.": "Обнаруживает и регистрирует без блокировки. Для анализа и первичного запуска, не для постоянной работы.",
    "Erkennt und protokolliert, erzwingt keine aktive Antwort.": "Обнаруживает и протоколирует, не применяет активный отклик.",
    "Erkennt und protokolliert, erzwingt keine aktive Antwort. Defender-Echtzeitschutz und Firewall-Grundschutz bleiben verpflichtend.": "Обнаруживает и журналирует без активного принуждения. Защита Defender в реальном времени и базовый брандмауэр остаются обязательными.",
    "Erkennt Win32-Speicherinjektions-Tokens wie VirtualAllocEx, WriteProcessMemory, CreateRemoteThread": "Обнаруживает токены инъекции памяти Win32, такие как VirtualAllocEx, WriteProcessMemory, CreateRemoteThread",
    "Erkennung": "Обнаружение",
