    "Evidenz und Schutzstatus werden abschließend verifiziert. Der Dialog bestätigt den Wechsel, sobald die Control Plane fertig ist.": "Доказательства и статус защиты проверяются окончательно. Диалог подтвердит переход, когда плоскость управления завершит работу.",
