    "Explizit geschützte öffentliche Management-IP/CIDR werden vor der WFP-Block-Generation mathematisch aus BLOCK-Prefixen subtrahiert. Die Threat-Intel-Korrelation bleibt unberührt.": "Явно защищенные публичные IP/CIDR управления математически вычитаются из префиксов BLOCK перед генерацией блокировок WFP. Корреляция Threat Intel остается неизменной.",
