    "Freigabe gespeichert und als Evidenzereignis protokolliert.": "Разрешение сохранено и занесено в журнал как событие-доказательство.",
    "Freigabe widerrufen": "Отозвать разрешение",
    "Freigabe widerrufen und als Evidenzereignis protokolliert.": "Разрешение отозвано и занесено в журнал как событие-доказательство.",
    "Freigabe wird entfernt …": "Разрешение удаляется …",
