    "Freigabe wird geprüft.": "Разрешение проверяется.",
    "Freigabe wird validiert …": "Разрешение проверяется …",
    "Freigeben (Whitelist)": "Разрешить (Белый список)",
    "Freigegebene Pfade oder IP-Ziele werden sofort aus aktiven Kernel-WFP-Sperren gelöst und künftig nicht mehr blockiert.": "Разрешённые пути или IP-адреса немедленно удаляются из активных блокировок WFP на уровне ядра и не будут блокироваться в дальнейшем.",
    "Für „{0}“ werden echte Windows-Firewall-Regeln (ausgehend und eingehend, Aktion Block) erzeugt. Die Transaktion wird protokolliert und kann über „Sperre aufheben“ zurückgenommen werden.": "Для «{0}» создаются реальные правила брандмауэра Windows (исходящие и входящие, действие «Блок»). Транзакция протоколируется и может быть отменена через «Снять блокировку».",
    "Für Alltag, Browser, Kommunikation und persönliche Dateien. Empfohlen: vollständiger Defender-Schutz, ASR/CFA im Blockmodus, Firewall, Titan STRICT und Integritätsüberwachung.": "Для повседневных задач, браузера, общения и личных файлов. Рекомендуется: полная защита Defender, ASR/CFA в режиме блокировки, брандмауэр, Titan STRICT и контроль целостности.",
    "Für Arbeitsplätze mit geschäftlichen Daten und mehreren Schutzschichten. Empfohlen: EnterpriseBalanced, alle ASR-Regeln im Blockmodus, CFA, Firewall, Titan STRICT und lückenlose Evidenz.": "Для рабочих мест с деловыми данными и многоуровневой защитой. Рекомендуется: EnterpriseBalanced, все правила ASR в режиме блокировки, CFA, брандмауэр, Titan STRICT и полная цепочка доказательств.",
    "Für dauerhaft laufende Systeme ohne lokale Bedienung. Empfohlen: Isolation-Profil mit zusätzlich deaktiviertem USB-Speicher und RDP, Defender vollständig blockierend, Firewall und Titan STRICT.": "Для систем непрерывной работы без локального оператора. Рекомендуется: профиль изоляции с отключёнными USB-накопителями и RDP, полная блокировка Defender, брандмауэр и Titan STRICT.",
    "Für die Aktivierung ist eine Operator-Sitzung erforderlich. Bitte über das Security Center anmelden und erneut versuchen.": "Для активации требуется сеанс оператора. Войдите через Security Center и повторите попытку.",
    "Für diese Komponente ist keine feingranulare Konfiguration vorgesehen; sie wird als Ganzes angewendet oder zurückgerollt.": "Для этого компонента не предусмотрена детальная конфигурация; он применяется или откатывается целиком.",
    "Für eine unabhängige Prüfung.": "Для независимой проверки.",
    "Für lokale Entwicklung und Builds. Empfohlen: EnterpriseBalanced, Defender blockierend, Titan STRICT mit Entwicklungsbaum und expliziten Owner-Prozessketten. Automatische Quarantäne bleibt hier aus.": "Для локальной разработки и сборок. Рекомендуется: EnterpriseBalanced, блокирующий Defender, Titan STRICT с корневой папкой разработки и доверенной цепочкой процессов. Автокарантин отключён.",
    "geblockt": "заблокировано",
    "GeDefense": "GeDefense",
    "GEDEFENSE · SYSTEMBEREITSCHAFT": "GEDEFENSE · ГОТОВНОСТЬ СИСТЕМЫ",
    "GeDefense ist bereit": "GeDefense готов",
    "GeDefense ist bereit.": "GeDefense готов к работе.",
    "GeDefense misst Defender, Firewall, Telemetrie und Threat Intelligence. MHX bewertet Prozesse, beendet aber keine Prozesse. Die Schutzlage ist sichtbar, ohne dass die Control Plane eingreift.": "GeDefense измеряет Defender, брандмауэр, телеметрию и разведку угроз. MHX оценивает процессы, но не завершает их. Картина защиты видна без вмешательства плоскости управления.",
    "GeDefense Navigation": "Навигация GeDefense",
    "GeDefense nutzt Windows-eigene TCP-Tabellen und verbindet Threat-Intel-Treffer ohne zusätzliche Runtime mit MHX.": "GeDefense использует собственные TCP-таблицы Windows и связывает совпадения Threat Intel с MHX без дополнительной среды выполнения.",
    "GeDefense Titan · {0}": "GeDefense Titan · {0}",
