    "Hebt die Mindest-Schwere für Benachrichtigungen auf CRITICAL an; deaktiviert bleiben LOW und höher sichtbar.": "Повышает минимальную критичность уведомлений до CRITICAL; при отключении остаются видимыми LOW и выше.",
