    "Hinzufügen": "Добавить",
    "HMAC-verkettete Ereignisse, serverseitig paginiert.": "События со связью HMAC, с серверной постраничной разбивкой.",
    "HMAC-verkettete Security-Ereignisse machen nachträgliche Manipulation detektierbar. Angezeigt werden seitenweise die neuesten Einträge; es gibt keine endlose Liste.": "События безопасности, связанные HMAC, позволяют обнаружить последующую подмену. Отображаются последние записи постранично; бесконечного списка нет.",
    "Höchste Eingriffstiefe: Enforcement und Default-Deny.": "Максимальная глубина вмешательства: принуждение и запрет по умолчанию.",
    "Hohe Risiken entstehen aus geschützten Pfaden, Persistenz, Sicherheits-Downgrades und ausführbaren Ingress-Objekten — nicht aus einer einzelnen Vermutung.": "Высокие риски возникают из защищенных путей, закрепления, понижения уровня безопасности и исполняемых объектов входящего трафика — а не из одного предположения.",
