    "Kinetic × TI": "Kinetic × TI",
    "Kinetic Armed bedeutet aktive Korrelation, nicht die Installation neuer Kinetic-Sperrregeln. Separate dynamische Blocks benötigen einen eigenen, getesteten Enforcement-/Rollback-Mechanismus.": "Kinetic Armed означает активную корреляцию, а не установку новых правил блокировки Kinetic. Отдельные динамические блокировки требуют собственного протестированного механизма применения/отката.",
    "Kinetic bewaffnet, Threat-IP-Generation nicht verifiziert": "Kinetic активен, генерация Threat-IP не подтверждена",
    "Kinetic Defense": "Kinetic Defense",
    "KINETIC DEFENSE // WINDOWS": "KINETIC DEFENSE // WINDOWS",
    "Kinetic erkennt auffällige WFP-Sperrhaufen ohne neue Firewall-Regeln zu installieren.": "Kinetic выявляет подозрительные скопления блокировок WFP, не устанавливая новые правила брандмауэра.",
    "Kinetic Execution & Lineage Defense": "Кинетическое исполнение и защита цепочки происхождения",
    "KINETIC GEO INTELLIGENCE // LOCAL ONLY": "KINETIC GEO INTELLIGENCE // ТОЛЬКО ЛОКАЛЬНО",
    "Kinetic korreliert Burst-Signale mit Threat-IP-Feeds. Als blockiert gelten ausschließlich tatsächlich beobachtete, unserer WFP-Regelgeneration zugeordnete Sperren.": "Kinetic коррелирует сигналы всплесков с потоками Threat-IP. Заблокированными считаются только фактически наблюдаемые блокировки, отнесенные к нашей генерации правил WFP.",
    "Kinetic nach einem Neustart erneut scharfschalten, sobald die verifizierten WFP/Threat-IP-Anforderungen erfüllt sind.": "Повторно взводить Kinetic после перезагрузки при выполнении требований WFP и Threat-IP.",
    "Kinetic Netzwerkereignisse auf einer Weltkarte": "Сетевые события Kinetic на мировой карте",
