    "Nur echte, von der Control Plane gemeldete Ereignisse erscheinen im Notification Center.": "В Центре уведомлений отображаются только реальные события, о которых сообщила плоскость управления.",
    "Nur eine gültige, begrenzte Freigabe macht eine Änderung autorisiert — Adminrechte allein nicht.": "Изменение авторизует только действительное ограниченное разрешение — не права администратора сами по себе.",
    "Nur für neue ausführbare oder skriptfähige Objekte in geschützten Ingress-/Systempfaden, nie für normale Dokumente.": "Только для новых исполняемых или скриптовых объектов в защищенных путях входящего трафика/системных путях, никогда для обычных документов.",
