    "Erkennt Angriffe auf Anmeldeinformationen wie MiniDumpWriteDump, Sekurlsa und SAM-Export": "检测凭据攻击，例如 MiniDumpWriteDump、Sekurlsa 和 SAM 导出",
    "Erkennt Base64-obfuskierte Befehlsblöcke ab 60 Zeichen oder fortlaufende Hex-Payloads": "检测长度 60 字符以上的 Base64 混淆命令块或连续十六进制载荷",
    "Erkennt bösartige Living-off-the-Land Parameter wie -enc, -decode, encodedcommand, downloadstring, invoke-expression": "检测恶意 living-off-the-land 参数，例如 -enc、-decode、encodedcommand、downloadstring、invoke-expression",
    "Erkennt das Löschen von Schattenkopien (vssadmin delete), BITS-Transfers und Certutil-Downloads": "检测卷影副本删除（vssadmin delete）、BITS 传输与 Certutil 下载",
    "Erkennt Log4j/JNDI Remote-Exploits sowie Mining-Protokolle (Stratum, Monero, Coinhive)": "检测 Log4j/JNDI 远程漏洞利用以及挖矿协议（Stratum、Monero、Coinhive）",
    "Erkennt und protokolliert, blockiert nicht. Für Analyse und Erstinbetriebnahme, nicht als Dauerzustand.": "仅检测和记录而不阻断。适用于分析与初次启用，不作为长期模式。",
    "Erkennt und protokolliert, erzwingt keine aktive Antwort.": "仅检测并记录，不强制执行主动响应。",
    "Erkennt und protokolliert, erzwingt keine aktive Antwort. Defender-Echtzeitschutz und Firewall-Grundschutz bleiben verpflichtend.": "仅检测与记录，不强制主动拦截。Defender 实时防护与基础防火墙仍为强制要求。",
    "Erkennt Win32-Speicherinjektions-Tokens wie VirtualAllocEx, WriteProcessMemory, CreateRemoteThread": "检测 Win32 内存注入标记，例如 VirtualAllocEx、WriteProcessMemory、CreateRemoteThread",
