    "Freigeben (Whitelist)": "放行（白名单）",
    "Freigegebene Pfade oder IP-Ziele werden sofort aus aktiven Kernel-WFP-Sperren gelöst und künftig nicht mehr blockiert.": "放行的路径或 IP 目标将立即从活动内核 WFP 阻断中解除，且未来不再被阻断。",
    "Für „{0}“ werden echte Windows-Firewall-Regeln (ausgehend und eingehend, Aktion Block) erzeugt. Die Transaktion wird protokolliert und kann über „Sperre aufheben“ zurückgenommen werden.": "将为“{0}”创建真实的 Windows 防火墙规则（出站和入站，操作：阻止）。该事务会记录到日志，并可通过“解除阻止”撤销。",
    "Für Alltag, Browser, Kommunikation und persönliche Dateien. Empfohlen: vollständiger Defender-Schutz, ASR/CFA im Blockmodus, Firewall, Titan STRICT und Integritätsüberwachung.": "适用于日常使用、浏览器、通讯与个人文件。推荐配置：完整的 Defender 防护、ASR/CFA 阻断模式、防火墙、Titan STRICT 与完整性监控。",
    "Für Arbeitsplätze mit geschäftlichen Daten und mehreren Schutzschichten. Empfohlen: EnterpriseBalanced, alle ASR-Regeln im Blockmodus, CFA, Firewall, Titan STRICT und lückenlose Evidenz.": "适用于处理业务数据的多层级防护工作站。推荐配置：EnterpriseBalanced、全部 ASR 规则阻断模式、CFA、防火墙、Titan STRICT 与完整证据链。",
    "Für dauerhaft laufende Systeme ohne lokale Bedienung. Empfohlen: Isolation-Profil mit zusätzlich deaktiviertem USB-Speicher und RDP, Defender vollständig blockierend, Firewall und Titan STRICT.": "适用于无本地操作的长时运行系统。推荐配置：隔离模式并禁用 USB 存储与 RDP、全面阻断的 Defender、防火墙及 Titan STRICT。",
    "Für die Aktivierung ist eine Operator-Sitzung erforderlich. Bitte über das Security Center anmelden und erneut versuchen.": "激活需要操作员会话。请通过安全中心登录后重试。",
    "Für diese Komponente ist keine feingranulare Konfiguration vorgesehen; sie wird als Ganzes angewendet oder zurückgerollt.": "此组件不支持细粒度配置；将整体应用或整体回滚。",
    "Für eine unabhängige Prüfung.": "用于独立检查。",
    "Für lokale Entwicklung und Builds. Empfohlen: EnterpriseBalanced, Defender blockierend, Titan STRICT mit Entwicklungsbaum und expliziten Owner-Prozessketten. Automatische Quarantäne bleibt hier aus.": "适用于本地开发与构建。推荐配置：EnterpriseBalanced、阻断模式的 Defender、搭配开发目录与所有者信任链的 Titan STRICT。自动隔离在此模式下关闭。",
